function Chip({label,active,onPress}:any){return <Pressable onPress={onPress} style={[s.chip,active&&s.chipActive]}><Text style={{fontSize:13,color:active?C.teal:C.muted}}>{label}</Text></Pressable>}
function Action({title,icon,onPress}:any){return <Pressable onPress={onPress} style={s.action}><Ionicons name={icon} size={22} color={C.teal}/><Text style={s.actionText}>{title}</Text></Pressable>}
function Empty({title,sub,icon,cta,onPress}:any){return <View style={s.empty}><View style={s.emptyIcon}><Ionicons name={icon||'car-outline'} size={29} color={C.teal}/></View><Text style={s.emptyTitle}>{title}</Text><Text style={s.emptySub}>{sub}</Text>{cta?<Button title={cta} onPress={onPress}/>:null}</View>}
