function LeadSection({items,onStatusChange,showPopup}:any){
 const statusAction=(item:any,label:string,status:string)=>({text:label,onPress:()=>onStatusChange?.(item.id,status,item.kind)});
 return items.length?<View style={{gap:10,marginTop:14}}>{items.map((x:any)=><Glass key={x.id} style={{padding:13}}><Text style={s.carName}>{x.title}</Text><Text style={s.muted}>{x.buyer} → {x.seller} · {x.kind}</Text><Text style={s.description}>{x.message}</Text><Pressable onPress={()=>{const actions=x.kind==='Test drive'?[...(x.status==='Requested'?[statusAction(x,'Confirm','CONFIRMED')]:[]),...(x.status==='Confirmed'?[statusAction(x,'Mark completed','COMPLETED')]:[]),...(!['Completed','Cancelled'].includes(x.status)?[statusAction(x,'Cancel','CANCELLED')]:[]),{text:'Cancel dialog',style:'cancel'}]:[statusAction(x,'New','NEW'),statusAction(x,'Contacted','CONTACTED'),statusAction(x,'In progress','IN_PROGRESS'),statusAction(x,'Closed','CLOSED'),{text:'Cancel dialog',style:'cancel'}];showPopup?.(x.kind==='Test drive'?'Update test drive':'Update enquiry','Choose the next status',actions as any)}}><Text style={s.link}>Status: {x.status} · Update</Text></Pressable></Glass>)}</View>:<Empty title="No leads yet" sub="Customer enquiries and test-drive requests will appear here." icon="chatbubbles-outline"/>;
}
