 useEffect(()=>{let active=true;if(user?.role==='Customer'){api.favorites().then(items=>{if(active)setSaved(items.map((item:any)=>String(item.car?.id||item.carId)).filter(Boolean))}).catch(()=>{})}else if(user?.role==='Dealer'){setSaved([])}return()=>{active=false}},[user?.role]);
 useEffect(()=>{let active=true;if(user?.role==='Dealer'){api.dealerCars().then(items=>{if(!active)return;const mapped:Car[]=items.map((car:any)=>{const statusMap:Record<string,ListingStatus>={DRAFT:'Draft',PENDING_APPROVAL:'Pending Review',AVAILABLE:'Published',RESERVED:'Reserved',SOLD:'Sold',ARCHIVED:'Paused',REJECTED:'Pending Review'};return {id:String(car.id),title:String(car.title||[car.brand?.name,car.model?.name].filter(Boolean).join(' ')||'Vehicle'),brand:String(car.brand?.name||''),model:String(car.model?.name||''),variant:String(car.variant||'Standard'),year:Number(car.manufacturingYear)||new Date().getFullYear(),price:Number(car.priceInr)||0,km:Number(car.mileageKm)||0,fuel:String(car.fuelType||'PETROL').toLowerCase().replace(/^./,(v:string)=>v.toUpperCase()),transmission:String(car.transmission||'MANUAL').toLowerCase().replace(/^./,(v:string)=>v.toUpperCase()),owners:Number(car.ownershipCount)||1,location:[car.city,car.state].filter(Boolean).join(', '),image:String(car.images?.find((image:any)=>image.isCover)?.imageUrl||car.images?.[0]?.imageUrl||HERO),rating:'—',status:statusMap[String(car.status)]||'Draft',seller:user.name,sellerType:'Dealer',description:String(car.description||'') }});setCars(prev=>[...prev.filter(c=>c.seller!==user.name),...mapped])}).catch((e:any)=>{if(active)setToast(e?.message||'Could not load dealer inventory')})}return()=>{active=false}},[user?.role,user?.name]);
 useEffect(()=>{let active=true;if(user?.role!=='Dealer')return()=>{active=false};(async()=>{try{
  const [expenseRows,saleRows,carLeads,testDriveRows]=await Promise.all([api.dealerExpenses(),api.dealerSales(),api.dealerEnquiries('CAR_ENQUIRY'),api.dealerTestDrives()]);
  if(!active)return;
  setExpenses(expenseRows.map((item:any)=>({id:String(item.id),carId:String(item.carId),carTitle:String(item.carTitle||'Vehicle'),amount:Number(item.amount)||0,category:String(item.category||'Other'),note:String(item.note||''),date:item.date?new Date(item.date).toLocaleDateString('en-IN'):''})));
  setSales(saleRows.map((item:any)=>({id:String(item.id),carId:String(item.carId),title:String(item.title||item.carTitle||'Vehicle'),price:Number(item.price??item.salePrice)||0,cost:Number(item.cost??item.acquisitionCost)||0,expenses:Number(item.expenses)||0,profit:Number(item.profit)||0,date:item.date?new Date(item.date).toLocaleDateString('en-IN'):''})));
  const enquiryStatus:Record<string,string>={NEW:'New',OPEN:'Open',CONTACTED:'Contacted',IN_PROGRESS:'In progress',CLOSED:'Closed'};
  const driveStatus:Record<string,string>={REQUESTED:'Requested',CONFIRMED:'Confirmed',COMPLETED:'Completed',CANCELLED:'Cancelled'};
  const mappedLeads=carLeads.map((item:any)=>({id:String(item.id),carId:String(item.carId||item.car?.id||''),title:String(item.car?.title||'Vehicle enquiry'),seller:user.name,buyer:String(item.customer?.name||'Customer'),message:String(item.message||''),status:enquiryStatus[String(item.status)]||String(item.status||'New'),kind:'Enquiry',date:item.createdAt?new Date(item.createdAt).toLocaleDateString('en-IN'):''}));
  const mappedDrives=testDriveRows.map((item:any)=>({id:String(item.id),carId:String(item.carId||item.car?.id||''),title:String(item.car?.title||'Test drive request'),seller:user.name,buyer:String(item.customer?.name||'Customer'),message:String(item.notes||'Test-drive request'),status:driveStatus[String(item.status)]||String(item.status||'Requested'),kind:'Test drive',date:item.scheduledAt?new Date(item.scheduledAt).toLocaleString('en-IN'):''}));
  setEnquiries([...mappedLeads,...mappedDrives]);
 }catch(e:any){if(active)setToast(e?.message||'Could not load dealer records from the backend')}})();return()=>{active=false}},[user?.role,user?.name]);
 const notify=(m:string)=>{if(screen!=='app'){setPopup({title:'SM Associate Cars',message:m,icon:/success|welcome|created/i.test(m)?'checkmark-circle-outline':'information-circle-outline'});return;}setToast(m);setTimeout(()=>setToast(''),2500)};
 const showPopup=(title:string,message:string,actions?:any[],options:any={})=>setPopup({title,message,actions,...options});
